<?php
/** Review rounds 22–23 — conference lobby privacy and deterministic speaker-queue hardening. */
declare(strict_types=1);
defined('ABSPATH') || exit;

final class SN_Future24_Review_Hardening_D {
    public static function register():void{add_action('rest_api_init',[self::class,'routes'],1980);}
    public static function routes():void{
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/lobby',['methods'=>'GET','callback'=>[self::class,'call_lobby'],'permission_callback'=>[SN_REST::class,'access']],true);
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/hand-raise',['methods'=>'POST','callback'=>[self::class,'hand_raise'],'permission_callback'=>[SN_REST::class,'access']],true);
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/speaker-queue',[['methods'=>'GET','callback'=>[self::class,'speaker_queue'],'permission_callback'=>[SN_REST::class,'access']],['methods'=>'POST','callback'=>[self::class,'manage_speaker_queue'],'permission_callback'=>[SN_REST::class,'access']]]);
    }
    public static function call_lobby(WP_REST_Request $r):WP_REST_Response|WP_Error{
        global $wpdb;$call=absint($r['id']);$user=get_current_user_id();if(!self::call_member($call,$user))return self::not_found();$manager=self::call_manager($call,$user);$sql="SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-17' AND scope_type='call' AND scope_id=%d AND state='active'";$args=[$call];if(!$manager){$sql.=' AND owner_id=%d';$args[]=$user;}$sql.=' ORDER BY id ASC LIMIT 200';$rows=$wpdb->get_results($wpdb->prepare($sql,...$args));$items=[];foreach(is_array($rows)?$rows:[] as $row){$d=self::decode($row);if(is_wp_error($d))continue;$items[]=['user_id'=>(int)($d['user_id']??$row->owner_id),'state'=>(string)($d['state']??'waiting'),'moderated_by'=>$manager?(int)($d['moderated_by']??0):0];}return rest_ensure_response(['call_id'=>$call,'lobby'=>$items,'view'=>$manager?'moderator':'self','privacy_minimized'=>!$manager]);
    }
    public static function hand_raise(WP_REST_Request $r):WP_REST_Response|WP_Error{
        global $wpdb;$call=absint($r['id']);$user=get_current_user_id();if(!self::call_member($call,$user))return self::not_found();$raised=rest_sanitize_boolean($r->get_param('raised'));$rows=self::feature_rows('F17-FUT-18',$call);$position=0;if($raised){foreach($rows as $row){$d=self::decode($row);if(!is_wp_error($d)&&!empty($d['raised']))$position=max($position,(int)($d['position']??0));}$position++;}$data=['user_id'=>$user,'raised'=>$raised,'position'=>$raised?$position:0,'speaking'=>false,'raised_at'=>$raised?current_time('mysql',true):null];$id=self::upsert('F17-FUT-18',$user,$call,$data,'hand:'.$call.':'.$user);if(is_wp_error($id))return $id;SN_DB::audit('future_hand_raise','call',$call,'success',['raised'=>$raised,'position'=>$data['position']],$user);return rest_ensure_response(['call_id'=>$call,'raised'=>$raised,'position'=>$data['position']]);
    }
    public static function speaker_queue(WP_REST_Request $r):WP_REST_Response|WP_Error{
        $call=absint($r['id']);$user=get_current_user_id();if(!self::call_member($call,$user))return self::not_found();$items=self::queue_items($call);return rest_ensure_response(['call_id'=>$call,'items'=>$items,'ordered'=>true]);
    }
    public static function manage_speaker_queue(WP_REST_Request $r):WP_REST_Response|WP_Error{
        global $wpdb;$call=absint($r['id']);$actor=get_current_user_id();if(!self::call_manager($call,$actor))return new WP_Error('forbidden','Call host permission is required.',['status'=>403]);$action=sanitize_key((string)$r->get_param('action'));
        if($action==='reorder'){$order=array_values(array_unique(array_filter(array_map('absint',(array)$r->get_param('user_ids')))));$rows=self::feature_rows('F17-FUT-18',$call);$map=[];foreach($rows as $row){$d=self::decode($row);if(!is_wp_error($d)&&!empty($d['raised']))$map[(int)($d['user_id']??$row->owner_id)]=$row;}if(array_diff(array_keys($map),$order)||array_diff($order,array_keys($map)))return new WP_Error('sn_speaker_queue_order_invalid','Reorder must contain each currently raised participant exactly once.',['status'=>409]);$pos=1;foreach($order as $uid){if(!self::call_member($call,$uid))return new WP_Error('sn_speaker_queue_member_changed','A queued participant is no longer in the call.',['status'=>409]);$row=$map[$uid];$d=self::decode($row);$d['position']=$pos++;$ok=self::save_row($row,$d);if(is_wp_error($ok))return $ok;}SN_DB::audit('future_speaker_queue_reordered','call',$call,'success',['order'=>$order],$actor);return rest_ensure_response(['call_id'=>$call,'items'=>self::queue_items($call)]);}
        if($action==='next'){$items=self::queue_items($call);if(!$items)return rest_ensure_response(['call_id'=>$call,'speaker_id'=>0,'items'=>[]]);$next=(int)$items[0]['user_id'];foreach(self::feature_rows('F17-FUT-18',$call) as $row){$d=self::decode($row);if(is_wp_error($d))continue;$uid=(int)($d['user_id']??$row->owner_id);$d['speaking']=$uid===$next;$d['raised']=$uid===$next?false:(bool)($d['raised']??false);if($uid===$next)$d['position']=0;$saved=self::save_row($row,$d);if(is_wp_error($saved))return $saved;}SN_DB::audit('future_speaker_advanced','call',$call,'success',['speaker_id'=>$next],$actor);return rest_ensure_response(['call_id'=>$call,'speaker_id'=>$next,'items'=>self::queue_items($call)]);}
        return new WP_Error('sn_speaker_queue_action_invalid','Use reorder or next.',['status'=>400]);
    }
    private static function queue_items(int $call):array{$items=[];foreach(self::feature_rows('F17-FUT-18',$call) as $row){$d=self::decode($row);if(is_wp_error($d)||empty($d['raised']))continue;$uid=(int)($d['user_id']??$row->owner_id);if(!self::call_member($call,$uid))continue;$items[]=['user_id'=>$uid,'position'=>(int)($d['position']??PHP_INT_MAX),'speaking'=>(bool)($d['speaking']??false),'raised_at'=>$d['raised_at']??null];}usort($items,static fn($a,$b)=>($a['position']<=>$b['position'])?:($a['user_id']<=>$b['user_id']));return $items;}
    private static function feature_rows(string $feature,int $call):array{global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id=%s AND scope_type='call' AND scope_id=%d AND state='active' ORDER BY id ASC LIMIT 500",$feature,$call));return is_array($rows)?$rows:[];}
    private static function upsert(string $feature,int $owner,int $call,array $data,string $client):int|WP_Error{global $wpdb;$key=hash('sha256',$client);$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE client_key=%s LIMIT 1",$key));$dummy=$row?:((object)['feature_id'=>$feature,'owner_id'=>$owner,'scope_type'=>'call','scope_id'=>$call,'version'=>0]);$cipher=self::encode($dummy,$data);if(is_wp_error($cipher))return $cipher;$now=current_time('mysql',true);if($row){$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'state'=>'active','updated_at'=>$now,'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);return $ok===1?(int)$row->id:new WP_Error('sn_future_conflict','Advanced communication state changed concurrently.',['status'=>409]);}$ok=$wpdb->insert($wpdb->prefix.'sn_future_records',['feature_id'=>$feature,'owner_id'=>$owner,'scope_type'=>'call','scope_id'=>$call,'state'=>'active','payload_cipher'=>$cipher,'client_key'=>$key,'created_at'=>$now,'updated_at'=>$now,'version'=>1]);return $ok===false?new WP_Error('database_error','Advanced communication change could not be stored safely.',['status'=>500]):(int)$wpdb->insert_id;}
    private static function save_row(object $row,array $data):bool|WP_Error{global $wpdb;$cipher=self::encode($row,$data);if(is_wp_error($cipher))return $cipher;$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'updated_at'=>current_time('mysql',true),'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);return $ok===1?true:new WP_Error('sn_future_conflict','Advanced communication state changed concurrently.',['status'=>409]);}
    private static function call_member(int $call,int $u):bool{global $wpdb;return(bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM ".SN_DB::table('call_members')." WHERE call_id=%d AND user_id=%d AND status IN ('invited','joined') LIMIT 1",$call,$u));}
    private static function call_manager(int $call,int $u):bool{global $wpdb;$c=(int)$wpdb->get_var($wpdb->prepare('SELECT conversation_id FROM '.SN_DB::table('calls').' WHERE id=%d',$call));if(!$c)return false;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-20' AND scope_type='call' AND scope_id=%d AND state='active' ORDER BY id DESC LIMIT 1",$call));if($rows){$d=self::decode($rows[0]);if(!is_wp_error($d)&&(int)($d['host_id']??0)===$u)return true;}return in_array(SN_DB::member_role($c,$u),['owner','moderator'],true)||current_user_can('manage_options');}
    private static function decode(object $row):array|WP_Error{$p=SN_Communication_Crypto::decrypt((string)$row->payload_cipher,'future-record|'.(string)$row->feature_id.'|'.(int)$row->owner_id.'|'.(string)$row->scope_type.'|'.(int)$row->scope_id);if(is_wp_error($p))return $p;$d=json_decode($p,true);return is_array($d)?$d:new WP_Error('sn_future_record_invalid','Advanced communication data is invalid.',['status'=>500]);}
    private static function encode(object $row,array $data):string|WP_Error{return SN_Communication_Crypto::encrypt((string)wp_json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),'future-record|'.(string)$row->feature_id.'|'.(int)$row->owner_id.'|'.(string)$row->scope_type.'|'.(int)$row->scope_id);}
    private static function not_found():WP_Error{return new WP_Error('not_found','Requested communication object is unavailable.',['status'=>404]);}
}
